document.addEventListener("DOMContentLoaded",function(){const completarBtns=document.querySelectorAll(".btn-completar");completarBtns.forEach((btn)=>{btn.addEventListener("click",function(e){e.preventDefault();const leccionId=this.dataset.leccion;const csrfMeta=document.querySelector('meta[name="csrf-token"]');const csrfToken=csrfMeta ? csrfMeta.getAttribute('content'):'';var restoreBtn=lcLoader&&lcLoader.disableBtn(btn,'Guardando...');var root=window.__APP_ROOT__||'.';fetch(root+"/src/Core/funciones.php",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:`accion=completar&leccion=${leccionId}&csrf_token=${encodeURIComponent(csrfToken)}`,}).then((res)=>res.json()).then((data)=>{if(restoreBtn)restoreBtn();if(data.ok){alert(`🎉 Lección completada!+${data.puntos}puntos`);actualizarProgreso(data.nivel,data.puntos,data.badges);}else{alert("Error al completar la lección");}})['catch'](function(){if(restoreBtn)restoreBtn();});});});function actualizarProgreso(nivel,puntos,badges){const progressFill=document.querySelector(".progress-fill");if(progressFill){let porcentaje=Math.min((puntos%500)/5,100);progressFill.style.width=porcentaje+"%";}const levelSpan=document.querySelector(".user-nivel");if(levelSpan)levelSpan.textContent=nivel;const badgeContainer=document.querySelector(".badges-section");if(badgeContainer&&badges){badgeContainer.innerHTML="";badges.forEach((b)=>{let span=document.createElement("span");span.className="badge "+(b.tipo||"");span.textContent=b.nombre;badgeContainer.appendChild(span);});}}const animConfeti=()=>{const confeti=document.createElement("div");confeti.className="confeti";confeti.style.left=Math.random()*window.innerWidth+"px";document.body.appendChild(confeti);setTimeout(()=>confeti.remove(),1500);};const confetiBtns=document.querySelectorAll(".animate-confeti");confetiBtns.forEach((btn)=>{btn.addEventListener("click",()=>animConfeti());});});const authWrapper=document.querySelector(".auth-form-wrapper");const loginBtn=document.querySelector(".btn-primary.animate-glitch");const usernameInput=document.getElementById("nombre_usuario");const passwordInput=document.getElementById("contrasena");if(loginBtn&&authWrapper&&usernameInput&&passwordInput){const camposVacios=()=>{return(usernameInput.value.trim()===""||passwordInput.value.trim()==="");};loginBtn.addEventListener("click",function(e){if(camposVacios()){e.preventDefault();authWrapper.classList.add("glitch-close");const oldError=authWrapper.querySelector(".temp-error");if(oldError)oldError.remove();const errorMsg=document.createElement("div");errorMsg.className="mensaje error temp-error";errorMsg.innerHTML="⚠️ ERROR DE ACCESO:DATOS INSUFICIENTES";authWrapper.prepend(errorMsg);loginBtn.dataset.originalText=loginBtn.textContent;loginBtn.textContent="REINTENTAR...";setTimeout(()=>{if(authWrapper.classList.contains("glitch-close")){authWrapper.classList.remove("glitch-close");const tempError=authWrapper.querySelector(".temp-error");if(tempError){tempError.remove();}if(loginBtn.dataset.originalText){loginBtn.textContent=loginBtn.dataset.originalText;delete loginBtn.dataset.originalText;}}},2000);}});}(function(){const THEME_KEY="lc_advance_theme";const root=document.documentElement||document.body;function applyTheme(theme){if(theme==="dark"){document.documentElement.classList.add("dark");document.body.classList.remove("theme-light");}else{document.documentElement.classList.remove("dark");document.body.classList.add("theme-light");}}try{const saved=localStorage.getItem(THEME_KEY)||(window.matchMedia('(prefers-color-scheme:light)').matches ? 'light':'');if(saved)applyTheme(saved);}catch(e){}window.toggleDarkMode=function(){const isDark=document.documentElement.classList.contains("dark");applyTheme(isDark ? "light":"dark");try{localStorage.setItem(THEME_KEY,isDark ? "light":"dark");}catch(e){}return!isDark;};document.addEventListener("click",function(e){const target=e.target.closest&&e.target.closest(".dark-toggle");if(target){e.preventDefault();window.toggleDarkMode();}});})();(function(){function disableQuestionOptions(q,clickedBtn,isCorrect){const options=q.querySelectorAll(".quiz-option");options.forEach((o)=>{o.disabled=true;o.classList.add("disabled");if(o.dataset.correct==="true")o.classList.add("correct-selected");if(o===clickedBtn&&!isCorrect)o.classList.add("incorrect-selected");});}document.addEventListener("click",function(e){const btn=e.target.closest&&e.target.closest(".quiz-option");if(btn){const q=btn.closest(".quiz-question");const container=btn.closest(".quiz-container")||document;const isCorrect=btn.dataset.correct==="true";const feedbackMsg=btn.dataset.feedback||(isCorrect ? "✅ Correcto":"❌ Incorrecto");if(q)disableQuestionOptions(q,btn,isCorrect);let feedbackDiv=container.querySelector(".quiz-feedback");if(!feedbackDiv){feedbackDiv=document.createElement("div");feedbackDiv.className="quiz-feedback";container.appendChild(feedbackDiv);}if(container.querySelector("#pollutionQuizFeedback")){window.pollutionQuizScore=(window.pollutionQuizScore||0)+(isCorrect ? 1:0);const answered=container.querySelectorAll(".quiz-option:disabled").length/(q ? q.querySelectorAll(".quiz-option").length:1);feedbackDiv.innerHTML=`<div class="${isCorrect ? "correct-feedback":"incorrect-feedback"}">${feedbackMsg}</div><p>Progreso:${answered}</p><p>Puntuación:${window.pollutionQuizScore}</p>`;}else{feedbackDiv.innerHTML=`<div class="${isCorrect ? "correct-feedback":"incorrect-feedback"}">${feedbackMsg}</div>`;}return;}const resetBtn=e.target.closest&&e.target.closest(".quiz-reset");if(resetBtn){const container=resetBtn.closest(".quiz-container");if(container){container.querySelectorAll(".quiz-option").forEach((button)=>{button.disabled=false;button.classList.remove("disabled","correct-selected","incorrect-selected",);button.style.backgroundColor="";button.style.color="";});const feedback=container.querySelector(".quiz-feedback");if(feedback)feedback.innerHTML="";if(window.pollutionQuizScore)window.pollutionQuizScore=0;}return;}});document.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){const active=document.activeElement;if(active&&active.classList&&active.classList.contains("quiz-option")){e.preventDefault();active.click();}}});})();document.addEventListener("DOMContentLoaded",function(){try{document.querySelectorAll(".quiz-option").forEach((btn)=>{btn.disabled=false;btn.classList.remove("disabled","correct-selected","incorrect-selected",);btn.style.display="";btn.style.visibility="";if(btn.tagName==="BUTTON")btn.type="button";});document.querySelectorAll(".quiz-feedback").forEach((f)=>{if(!f.textContent.trim())f.remove();});}catch(e){}const path=window.location.pathname;const href=window.location.href;const isPublicPage=path.includes('login.php')||path.includes('register.php')||path.includes('guest_login.php')||path.includes('quiz.php')||href.includes('login.php')||href.includes('register.php');if(!isPublicPage){fetchAndUpdateDashboard();setInterval(fetchAndUpdateDashboard,15000);}});function fetchAndUpdateDashboard(){var root=window.__APP_ROOT__||'.';fetch(root+"/api/ranking.php",{method:"GET",headers:{"Content-Type":"application/json"},}).then((res)=>{if(!res.ok){console.error("Response status:",res.status);throw new Error("HTTP error "+res.status);}return res.json();}).then((data)=>{console.log("Datos recibidos del ranking:",data);if(!data.ok){console.log("Error al obtener ranking:",data.error);return;}const puntosEl=document.getElementById("puntos-actuales");const nivelEl=document.getElementById("nivel-actual");const puntosProgressEl=document.getElementById("puntos-actuales-mini");const puntosNecesariosEl=document.getElementById("puntos-necesarios");if(puntosEl)puntosEl.textContent=data.puntos||0;if(nivelEl)nivelEl.textContent=data.nivel||1;if(puntosProgressEl)puntosProgressEl.textContent=data.puntos||0;const puntos_necesarios=((data.nivel||1)+1)*500;if(puntosNecesariosEl)puntosNecesariosEl.textContent=puntos_necesarios;const puntos_base=(data.nivel||1)*500;const progreso=Math.min(100,Math.max(0,(((data.puntos||0)-puntos_base)/500)*100),);const progressFill=document.getElementById("progress-fill");if(progressFill)progressFill.style.width=progreso+"%";const badgesContainer=document.getElementById("badges-container");if(badgesContainer&&data.badges){if(data.badges.length===0){badgesContainer.innerHTML='<p class="text-muted">¡Completa lecciones para obtener tu primer Badge(500 pts)!</p>';}else{badgesContainer.innerHTML=data.badges .map((b)=>`<span class="badge ${b.tipo||"bronze"}">${b.nombre}</span>`,).join("");}}const rankingBody=document.getElementById("ranking-body");console.log("rankingBody element:",rankingBody);console.log("data.ranking:",data.ranking);if(rankingBody&&data.ranking){if(data.ranking.length===0){rankingBody.innerHTML='<tr><td colspan="3" class="text-muted">Sé el primero en el ranking 🏆</td></tr>';}else{rankingBody.innerHTML=data.ranking .slice(0,10).map((player,idx)=>{const isCurrent=player.es_actual ? "ranking-current-user":"";return `<tr class="${isCurrent}"><td class="rank-number">${idx+1}</td><td class="rank-player">${player.nombre_usuario||"Anónimo"}</td><td class="rank-points">${player.puntos||0}pts</td></tr>`;}).join("");console.log("Ranking actualizado con "+data.ranking.length+" jugadores",);}}else{console.warn("rankingBody no existe o data.ranking no tiene datos");}}).catch((err)=>console.error("Error al actualizar dashboard:",err));}